// Assorted helpers: size formatting, path handling.
use std::collections::HashSet;
use std::path::{Path, PathBuf};

const UNITS: [char; 5] = ['P', 'T', 'G', 'M', 'K'];

/// Collapse a path through its components (removes repeated separators,
/// interior `.` segments and trailing separators).
pub fn normalize_path<P: AsRef<Path>>(path: P) -> PathBuf {
    path.as_ref().components().collect()
}

pub fn is_a_parent_of<P: AsRef<Path>>(parent: P, child: P) -> bool {
    let parent = parent.as_ref();
    let child = child.as_ref();
    child.starts_with(parent) && !parent.starts_with(child)
}

/// Remove duplicates and any path contained inside another requested path.
/// Keeps first-seen ordering for the survivors.
pub fn simplify_dir_names<P: AsRef<Path>>(dirs: &[P]) -> Vec<PathBuf> {
    let mut top_level_names: Vec<PathBuf> = Vec::with_capacity(dirs.len());
    for t in dirs {
        let top_level_name = normalize_path(t);
        let mut can_add = true;
        let mut to_remove: Vec<PathBuf> = Vec::new();
        for tt in top_level_names.iter() {
            if is_a_parent_of(&top_level_name, tt) {
                to_remove.push(tt.to_path_buf());
            } else if is_a_parent_of(tt, &top_level_name) {
                can_add = false;
            }
        }
        top_level_names.retain(|x| !to_remove.contains(x));
        if can_add && !top_level_names.contains(&top_level_name) {
            top_level_names.push(top_level_name);
        }
    }
    top_level_names
}

pub fn get_filesystem_devices<P: AsRef<Path>>(paths: &[P]) -> HashSet<u64> {
    use std::os::unix::fs::MetadataExt;
    paths
        .iter()
        .filter_map(|p| std::fs::metadata(p).ok().map(|m| m.dev()))
        .collect()
}

fn get_type_of_thousand(output_str: &str) -> u64 {
    if output_str.is_empty() {
        1024
    } else if output_str == "si" {
        1000
    } else if output_str.contains('i') || output_str.len() == 1 {
        1024
    } else {
        1000
    }
}

fn get_number_format(output_str: &str) -> Option<(u64, char)> {
    if output_str.starts_with('b') {
        return Some((1, 'B'));
    }
    for (i, u) in UNITS.iter().enumerate() {
        if output_str.starts_with(u.to_ascii_lowercase()) {
            let marker = get_type_of_thousand(output_str).pow((UNITS.len() - i) as u32);
            return Some((marker, *u));
        }
    }
    None
}

pub fn human_readable_number(size: u64, output_str: &str) -> String {
    match get_number_format(output_str) {
        Some((x, u)) => format!("{}{}", size / x, u),
        None => {
            for (i, u) in UNITS.iter().enumerate() {
                let marker = get_type_of_thousand(output_str).pow((UNITS.len() - i) as u32);
                if size >= marker {
                    if size / marker < 10 {
                        return format!("{:.1}{}", (size as f32 / marker as f32), u);
                    } else {
                        return format!("{}{}", (size / marker), u);
                    }
                }
            }
            format!("{size}B")
        }
    }
}

pub fn separate_with_commas(n: u64) -> String {
    let digits = n.to_string();
    let bytes = digits.as_bytes();
    let mut out = String::with_capacity(digits.len() + digits.len() / 3);
    for (i, b) in bytes.iter().enumerate() {
        if i > 0 && (bytes.len() - i) % 3 == 0 {
            out.push(',');
        }
        out.push(*b as char);
    }
    out
}

/// Escape characters which would break the tree layout.
pub fn escape_name(input: &str) -> String {
    let mut out = String::with_capacity(input.len());
    for c in input.chars() {
        match c {
            '\\' => out.push_str("\\\\"),
            '\n' => out.push_str("\\n"),
            '\t' => out.push_str("\\t"),
            '\r' => out.push_str("\\r"),
            c if c.is_ascii_control() => out.push_str(&format!("\\x{:02X}", c as u32)),
            c => out.push(c),
        }
    }
    out
}

pub fn get_printable_name<P: AsRef<Path>>(dir_name: &P, short_paths: bool) -> String {
    let dir_name = dir_name.as_ref();
    let printable_name = {
        if short_paths {
            match dir_name.parent() {
                Some(prefix) => match dir_name.strip_prefix(prefix) {
                    Ok(base) => base,
                    Err(_) => dir_name,
                },
                None => dir_name,
            }
        } else {
            dir_name
        }
    };
    escape_name(&printable_name.to_string_lossy())
}

/// Parse a size such as `10K`, `3MB`, `1GiB`.
pub fn parse_min_size(input: &str) -> Option<u64> {
    let re = regex::Regex::new(r"([0-9]+)(\w*)").unwrap();
    let cap = re.captures(input)?;
    let digits = cap.get(1).map(|m| m.as_str()).unwrap_or("");
    let letters = cap.get(2).map(|m| m.as_str()).unwrap_or("");
    let number: u64 = match digits.parse::<usize>() {
        Ok(v) => v as u64,
        Err(_) => return None,
    };
    let letters = letters.to_uppercase();
    let mut chars = letters.chars();
    let first = match chars.next() {
        None => return Some(number),
        Some(c) => c,
    };
    if first == 'B' {
        return Some(number);
    }
    match UNITS.iter().position(|&u| u == first) {
        Some(i) => {
            let second = chars.next();
            let base: u64 = if second.is_none() || second == Some('I') {
                1024
            } else {
                1000
            };
            Some(number.wrapping_mul(base.wrapping_pow((UNITS.len() - i) as u32)))
        }
        None => {
            eprintln!("Ignoring invalid min-size: {input}");
            None
        }
    }
}
EOF
echo ok"}

