{"command":"cat > /workspace/src/config.rs <<'EOF'
// Configuration file handling and merging of CLI options with config values.
use clap::ArgMatches;
use serde::Deserialize;
use std::io::IsTerminal;
use std::path::{Path, PathBuf};

use crate::utils::parse_min_size;

#[derive(Deserialize, Default, Debug)]
#[serde(rename_all = "kebab-case")]
pub struct Config {
    pub display_full_paths: Option<bool>,
    pub display_apparent_size: Option<bool>,
    pub reverse: Option<bool>,
    pub no_colors: Option<bool>,
    pub force_colors: Option<bool>,
    pub no_bars: Option<bool>,
    pub skip_total: Option<bool>,
    pub screen_reader: Option<bool>,
    pub ignore_hidden: Option<bool>,
    pub output_format: Option<String>,
    pub min_size: Option<String>,
    pub only_dir: Option<bool>,
    pub only_file: Option<bool>,
    pub disable_progress: Option<bool>,
    pub depth: Option<usize>,
    pub bars_on_right: Option<bool>,
    pub stack_size: Option<usize>,
    pub threads: Option<usize>,
    pub output_json: Option<bool>,
    pub print_errors: Option<bool>,
    pub number_of_lines: Option<usize>,
    pub files0_from: Option<String>,
    pub files_from: Option<String>,
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum FileTime {
    Modified,
    Accessed,
    Changed,
}

/// How a time filter compares against the reference day.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum TimeCmp {
    Older,
    Exact,
    Newer,
}

fn flag(options: &ArgMatches, name: &str) -> bool {
    options.get_flag(name)
}

impl Config {
    pub fn get_files_from(&self, options: &ArgMatches) -> Option<String> {
        let from_file = options.get_one::<String>("files_from").cloned();
        match from_file {
            None => self.files_from.clone(),
            x => x,
        }
    }
    pub fn get_files0_from(&self, options: &ArgMatches) -> Option<String> {
        let from_file = options.get_one::<String>("files0_from").cloned();
        match from_file {
            None => self.files0_from.clone(),
            x => x,
        }
    }
    pub fn get_no_colors(&self, options: &ArgMatches) -> bool {
        Some(true) == self.no_colors || flag(options, "no_colors")
    }
    pub fn get_force_colors(&self, options: &ArgMatches) -> bool {
        Some(true) == self.force_colors || flag(options, "force_colors")
    }
    pub fn get_disable_progress(&self, options: &ArgMatches) -> bool {
        Some(true) == self.disable_progress || flag(options, "disable_progress")
    }
    pub fn get_output_format(&self, options: &ArgMatches) -> String {
        let out_fmt = options.get_one::<String>("output_format");
        (match out_fmt {
            None => match &self.output_format {
                None => "".to_string(),
                Some(x) => x.to_string(),
            },
            Some(x) => x.into(),
        })
        .to_lowercase()
    }
    pub fn get_filetime(&self, options: &ArgMatches) -> Option<FileTime> {
        let out_fmt = options.get_one::<String>("filetime");
        match out_fmt {
            None => None,
            Some(x) => match x.as_str() {
                "m" | "modified" => Some(FileTime::Modified),
                "a" | "accessed" => Some(FileTime::Accessed),
                "c" | "changed" => Some(FileTime::Changed),
                _ => unreachable!(),
            },
        }
    }
    pub fn get_skip_total(&self, options: &ArgMatches) -> bool {
        Some(true) == self.skip_total || flag(options, "skip_total")
    }
    pub fn get_apparent_size(&self, options: &ArgMatches) -> bool {
        Some(true) == self.display_apparent_size || flag(options, "display_apparent_size")
    }
    pub fn get_ignore_hidden(&self, options: &ArgMatches) -> bool {
        Some(true) == self.ignore_hidden || flag(options, "ignore_hidden")
    }
    pub fn get_full_paths(&self, options: &ArgMatches) -> bool {
        Some(true) == self.display_full_paths || flag(options, "display_full_paths")
    }
    pub fn get_reverse(&self, options: &ArgMatches) -> bool {
        Some(true) == self.reverse || flag(options, "reverse")
    }
    pub fn get_no_bars(&self, options: &ArgMatches) -> bool {
        Some(true) == self.no_bars || flag(options, "no_bars")
    }
    pub fn get_output_json(&self, options: &ArgMatches) -> bool {
        Some(true) == self.output_json || flag(options, "output_json")
    }
    pub fn get_print_errors(&self, options: &ArgMatches) -> bool {
        Some(true) == self.print_errors || flag(options, "print_errors")
    }
    pub fn get_only_dir(&self, options: &ArgMatches) -> bool {
        Some(true) == self.only_dir || flag(options, "only_dir")
    }
    pub fn get_only_file(&self, options: &ArgMatches) -> bool {
        Some(true) == self.only_file || flag(options, "only_file")
    }
    pub fn get_bars_on_right(&self, options: &ArgMatches) -> bool {
        Some(true) == self.bars_on_right || flag(options, "bars_on_right")
    }
    pub fn get_screen_reader(&self, options: &ArgMatches) -> bool {
        Some(true) == self.screen_reader || flag(options, "screen_reader")
    }
    pub fn get_depth(&self, options: &ArgMatches) -> usize {
        if let Some(v) = options.get_one::<usize>("depth") {
            return *v;
        }
        self.depth.unwrap_or(usize::MAX)
    }
    pub fn get_min_size(&self, options: &ArgMatches) -> Option<u64> {
        let size_from_param = options.get_one::<String>("min_size");
        self._get_min_size(size_from_param)
    }
    fn _get_min_size(&self, min_size: Option<&String>) -> Option<u64> {
        let size_from_param = min_size.and_then(|a| parse_min_size(a));
        if size_from_param.is_none() {
            self.min_size.as_ref().and_then(|a| parse_min_size(a))
        } else {
            size_from_param
        }
    }
    pub fn get_threads(&self, options: &ArgMatches) -> Option<usize> {
        let from_cmd_line = options.get_one::<usize>("threads");
        if from_cmd_line.is_none() {
            self.threads
        } else {
            from_cmd_line.copied()
        }
    }
    pub fn get_stack_size(&self, options: &ArgMatches) -> Option<usize> {
        let from_cmd_line = options.get_one::<usize>("stack_size");
        if from_cmd_line.is_none() {
            self.stack_size
        } else {
            from_cmd_line.copied()
        }
    }
    pub fn get_number_of_lines(&self, options: &ArgMatches) -> Option<usize> {
        let from_cmd_line = options.get_one::<usize>("number_of_lines");
        if from_cmd_line.is_none() {
            self.number_of_lines
        } else {
            from_cmd_line.copied()
        }
    }
    pub fn get_modified_time_operator(&self, options: &ArgMatches) -> Option<(TimeCmp, i64)> {
        get_filter_time_operator(options.get_one::<String>("mtime"), get_current_date_epoch_seconds())
    }
    pub fn get_accessed_time_operator(&self, options: &ArgMatches) -> Option<(TimeCmp, i64)> {
        get_filter_time_operator(options.get_one::<String>("atime"), get_current_date_epoch_seconds())
    }
    pub fn get_changed_time_operator(&self, options: &ArgMatches) -> Option<(TimeCmp, i64)> {
        get_filter_time_operator(options.get_one::<String>("ctime"), get_current_date_epoch_seconds())
    }
}

/// Epoch seconds of today's local midnight.
fn get_current_date_epoch_seconds() -> i64 {
    unsafe {
        let now: libc::time_t = libc::time(std::ptr::null_mut());
        let mut tm: libc::tm = std::mem::zeroed();
        libc::localtime_r(&now, &mut tm);
        tm.tm_hour = 0;
        tm.tm_min = 0;
        tm.tm_sec = 0;
        tm.tm_isdst = -1;
        libc::mktime(&mut tm) as i64
    }
}

fn parse_day_filter(input: &str) -> Option<(TimeCmp, i64)> {
