}

impl Indicator {
    fn from_key(s: &str) -> Option<Indicator> {
        Some(match s {
            "no" => Indicator::Normal,
            "fi" => Indicator::RegularFile,
            "di" => Indicator::Directory,
            "ln" => Indicator::SymbolicLink,
            "pi" => Indicator::Fifo,
            "so" => Indicator::Socket,
            "do" => Indicator::Door,
            "bd" => Indicator::BlockDevice,
            "cd" => Indicator::CharacterDevice,
            "or" => Indicator::OrphanedSymbolicLink,
            "su" => Indicator::Setuid,
            "sg" => Indicator::Setgid,
            "st" => Indicator::Sticky,
            "ow" => Indicator::OtherWritable,
            "tw" => Indicator::StickyAndOtherWritable,
            "ex" => Indicator::ExecutableFile,
            "mi" => Indicator::MissingFile,
