            _ => return None,
        })
    }
}

pub struct LsColors {
    indicators: HashMap<Indicator, Style>,
    suffixes: Vec<(String, Option<Style>)>,
}

impl LsColors {
    fn empty() -> LsColors {
        LsColors {
            indicators: HashMap::new(),
            suffixes: Vec::new(),
        }
    }

    fn add_from_string(&mut self, input: &str) {
        for entry in input.split(':') {
            let parts: Vec<&str> = entry.split('=').collect();
            if parts.len() < 2 {
                continue;
            }
            let (key, value) = (parts[0], parts[1]);
            let style = Style::from_ansi_sequence(value);
            if let Some(suffix) = key.strip_prefix('*') {
                self.suffixes.push((suffix.to_lowercase(), style));
            } else if let Some(ind) = Indicator::from_key(key) {
                match style {
                    Some(s) => {
                        self.indicators.insert(ind, s);
                    }
                    None => {
                        self.indicators.remove(&ind);
                    }
                }
            }
        }
    }

    pub fn from_env() -> LsColors {
        let mut c = LsColors::empty();
        c.add_from_string(LS_COLORS_DEFAULT);
