const LS_COLORS_DEFAULT: &str = "rs=0:lc=\x1b[:rc=m:cl=\x1b[K:ex=01;32:sg=30;43:su=37;41:di=01;34:st=37;44:ow=34;42:tw=30;42:ln=01;36:bd=01;33:cd=01;33:do=01;35:pi=33:so=01;35:";

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum Colour {
    Black,
    Red,
    Green,
    Yellow,
    Blue,
    Purple,
    Cyan,
    White,
    Fixed(u8),
    Rgb(u8, u8, u8),
}

impl Colour {
    fn from_index(i: u8) -> Colour {
        match i {
            0 => Colour::Black,
            1 => Colour::Red,
            2 => Colour::Green,
            3 => Colour::Yellow,
            4 => Colour::Blue,
            5 => Colour::Purple,
            6 => Colour::Cyan,
            _ => Colour::White,
        }
    }
    fn code(&self, base: u8) -> String {
        match self {
            Colour::Black => format!("{}", base),
            Colour::Red => format!("{}", base + 1),
            Colour::Green => format!("{}", base + 2),
            Colour::Yellow => format!("{}", base + 3),
            Colour::Blue => format!("{}", base + 4),
            Colour::Purple => format!("{}", base + 5),
            Colour::Cyan => format!("{}", base + 6),
            Colour::White => format!("{}", base + 7),
            Colour::Fixed(n) => format!("{};5;{}", base + 8, n),
            Colour::Rgb(r, g, b) => format!("{};2;{};{};{}", base + 8, r, g, b),
        }
    }
}

#[derive(Clone, Copy, Debug, Default, PartialEq, Eq)]
pub struct Style {
    pub foreground: Option<Colour>,
    pub background: Option<Colour>,
    pub bold: bool,
    pub dimmed: bool,
    pub italic: bool,
    pub underline: bool,
    pub blink: bool,
    pub reverse: bool,
    pub hidden: bool,
    pub strikethrough: bool,
}

impl Style {
    pub fn fg(c: Colour) -> Style {
        Style {
            foreground: Some(c),
            ..Default::default()
        }
    }

    fn is_plain(&self) -> bool {
        *self == Style::default()
    }

    pub fn paint(&self, text: &str) -> String {
        if self.is_plain() {
            return text.to_string();
        }
        let mut codes: Vec<String> = Vec::new();
        if self.bold {
            codes.push("1".into());
        }
        if self.dimmed {
            codes.push("2".into());
        }
        if self.italic {
            codes.push("3".into());
        }
        if self.underline {
            codes.push("4".into());
        }
        if self.blink {
            codes.push("5".into());
        }
        if self.reverse {
            codes.push("7".into());
        }
        if self.hidden {
            codes.push("8".into());
        }
        if self.strikethrough {
            codes.push("9".into());
        }
        if let Some(bg) = self.background {
            codes.push(bg.code(40));
        }
        if let Some(fg) = self.foreground {
            codes.push(fg.code(30));
        }
        format!("\x1b[{}m{}\x1b[0m", codes.join(";"), text)
    }

    /// Parse an ANSI SGR sequence such as `01;34`.
    pub fn from_ansi_sequence(code: &str) -> Option<Style> {
        if code.is_empty() || code == "0" || code == "00" {
            return None;
        }
        let mut parts: std::collections::VecDeque<u8> = code
            .split(';')
            .map(|c| c.parse::<u8>().ok())
            .collect::<Option<_>>()?;
        let mut style = Style::default();
        loop {
            match parts.pop_front() {
                Some(0) => style = Style::default(),
                Some(1) => style.bold = true,
                Some(2) => style.dimmed = true,
                Some(3) => style.italic = true,
                Some(4) => style.underline = true,
                Some(5) | Some(6) => style.blink = true,
                Some(7) => style.reverse = true,
                Some(8) => style.hidden = true,
                Some(9) => style.strikethrough = true,
                Some(c @ 30..=37) => style.foreground = Some(Colour::from_index(c - 30)),
                Some(38) => match parse_extended(&mut parts) {
                    Some(c) => style.foreground = Some(c),
                    None => break,
                },
                Some(39) => style.foreground = None,
                Some(c @ 40..=47) => style.background = Some(Colour::from_index(c - 40)),
                Some(48) => match parse_extended(&mut parts) {
                    Some(c) => style.background = Some(c),
                    None => break,
                },
                Some(49) => style.background = None,
                Some(c @ 90..=97) => style.foreground = Some(Colour::Fixed(c - 90 + 8)),
                Some(c @ 100..=107) => style.background = Some(Colour::Fixed(c - 100 + 8)),
                Some(_) => {}
                None => break,
            }
        }
        Some(style)
    }
}

fn parse_extended(parts: &mut std::collections::VecDeque<u8>) -> Option<Colour> {
    match (parts.pop_front(), parts.pop_front()) {
        (Some(5), Some(n)) => Some(Colour::Fixed(n)),
        (Some(2), Some(r)) => match (parts.pop_front(), parts.pop_front()) {
            (Some(g), Some(b)) => Some(Colour::Rgb(r, g, b)),
            _ => None,
        },
        _ => None,
    }
}

#[derive(Clone, Copy, Debug, PartialEq, Eq, Hash)]
enum Indicator {
