fn sort_by_inode(a: &Node, b: &Node) -> Ordering {
    match (a.inode_device, b.inode_device) {
        (Some(x), Some(y)) => {
            if x.0 != y.0 {
                x.0.cmp(&y.0)
            } else if x.1 != y.1 {
                x.1.cmp(&y.1)
            } else {
                a.name.cmp(&b.name)
            }
        }
        (Some(_), None) => Ordering::Greater,
        (None, Some(_)) => Ordering::Less,
        (None, None) => a.name.cmp(&b.name),
    }
}

// Remove duplicate inodes (hard links) and compute the aggregated sizes.
fn clean_inodes(x: Node, inodes: &mut HashSet<(u64, u64)>, walk_data: &WalkData) -> Option<Node> {
    if !walk_data.use_apparent_size {
        if let Some(id) = x.inode_device {
            if !inodes.insert(id) {
                return None;
            }
        }
    }

    let mut tmp: Vec<_> = x.children;
    tmp.sort_by(sort_by_inode);
    let new_children: Vec<_> = tmp
        .into_iter()
        .filter_map(|c| clean_inodes(c, inodes, walk_data))
        .collect();

    let actual_size = if walk_data.by_filetime.is_some() {
        new_children
            .iter()
            .map(|c| c.size)
            .chain(std::iter::once(x.size))
            .max()
            .unwrap_or(0)
    } else {
        new_children
            .iter()
            .fold(x.size, |acc, c| acc.wrapping_add(c.size))
    };

    Some(Node {
        name: x.name,
        size: actual_size,
        children: new_children,
        inode_device: x.inode_device,
        depth: x.depth,
    })
}

pub fn is_filtered_out_due_to_regex(filter_regex: &[Regex], dir: &Path) -> bool {
    if filter_regex.is_empty() {
        false
    } else {
        let s = dir.as_os_str().to_string_lossy();
        filter_regex.iter().all(|f| !f.is_match(&s))
    }
}

pub fn is_filtered_out_due_to_invert_regex(filter_regex: &[Regex], dir: &Path) -> bool {
    if filter_regex.is_empty() {
        return false;
    }
    let s = dir.as_os_str().to_string_lossy();
    filter_regex.iter().any(|f| f.is_match(&s))
}

fn is_filtered_out_due_to_file_time(filter_time: &Option<(TimeCmp, i64)>, actual_time: i64) -> bool {
    match filter_time {
        None => false,
        Some((TimeCmp::Older, bound)) => actual_time > *bound,
        Some((TimeCmp::Newer, bound)) => actual_time < *bound,
        Some((TimeCmp::Exact, bound)) => {
            actual_time < bound.wrapping_sub(24 * 60 * 60) || actual_time >= *bound
        }
    }
}

fn time_filters_active(walk_data: &WalkData) -> bool {
    walk_data.filter_modified_time.is_some()
        || walk_data.filter_accessed_time.is_some()
        || walk_data.filter_changed_time.is_some()
}

fn filtered_by_times(walk_data: &WalkData, times: Times) -> bool {
    [
        (&walk_data.filter_modified_time, times.0),
        (&walk_data.filter_accessed_time, times.1),
        (&walk_data.filter_changed_time, times.2),
    ]
    .iter()
    .any(|(filter_time, actual_time)| is_filtered_out_due_to_file_time(filter_time, *actual_time))
}

fn ignore_file(entry: &fs::DirEntry, walk_data: &WalkData) -> bool {
    let is_dot_file = entry
        .file_name()
        .to_str()
        .unwrap_or("")
        .starts_with('.');
    let path = entry.path();
    let mut is_ignored_path = walk_data.ignore_directories.contains(&path);
    if !is_ignored_path && !walk_data.ignore_canonical.is_empty() {
        if let Ok(canon) = fs::canonicalize(&path) {
            is_ignored_path = walk_data.ignore_canonical.contains(&canon);
        }
    }
    let follow_links =
        walk_data.follow_links && entry.file_type().is_ok_and(|ft| ft.is_symlink());

    if !walk_data.allowed_filesystems.is_empty() {
        let size_inode_device = get_metadata(&path, false, follow_links);
        if let Some((_size, Some((_id, dev)), _times)) = size_inode_device {
            if !walk_data.allowed_filesystems.contains(&dev) {
                return true;
            }
        }
    }

    if time_filters_active(walk_data) {
        if let Some((_, _, times)) = get_metadata(&path, false, follow_links) {
            if path.is_file() && filtered_by_times(walk_data, times) {
                return true;
            }
        }
    }

    if !walk_data.filter_regex.is_empty()
        && path.is_file()
        && is_filtered_out_due_to_regex(walk_data.filter_regex, &path)
    {
        return true;
    }

    if !walk_data.invert_filter_regex.is_empty()
        && path.is_file()
        && is_filtered_out_due_to_invert_regex(walk_data.invert_filter_regex, &path)
    {
