    always_add_children(&display_data, r, &mut heap);
    fill_remaining_lines(heap, &root, &display_data, keep_collapsed)
}

fn fill_remaining_lines<'a>(
    mut heap: BinaryHeap<&'a Node>,
    root: &'a Node,
    display_data: &AggregateData,
    keep_collapsed: &HashSet<PathBuf>,
) -> DisplayNode {
    let mut allowed_nodes: HashSet<*const Node> = HashSet::new();
    let mut count = 0usize;
    let mut leaves: Vec<&Node> = Vec::new();

    while count < display_data.number_of_lines {
        let line = heap.pop();
        match line {
            Some(line) => {
                if !display_data.only_file || line.children.is_empty() {
                    allowed_nodes.insert(line as *const Node);
                    leaves.push(line);
                    count += 1;
                }
                add_children(display_data, line, &mut heap, keep_collapsed);
            }
            None => break,
        }
    }

    if display_data.only_file {
        let mut children: Vec<DisplayNode> = leaves
            .into_iter()
            .map(|n| DisplayNode {
                name: n.name.clone(),
                size: n.size,
                children: vec![],
            })
            .collect();
        children.sort_by(|a, b| b.cmp(a));
        return DisplayNode {
            name: root.name.clone(),
            size: root.size,
            children,
        };
    }
    recursive_rebuilder(&allowed_nodes, root)
}

fn add_children<'a>(
    display_data: &AggregateData,
    file_or_folder: &'a Node,
    heap: &mut BinaryHeap<&'a Node>,
    keep_collapsed: &HashSet<PathBuf>,
) {
    if display_data.depth > file_or_folder.depth && !keep_collapsed.contains(&file_or_folder.name) {
        heap.extend(
            file_or_folder
                .children
                .iter()
                .filter(|c| passes_filters(display_data, c)),
        )
    }
}

fn always_add_children<'a>(
    display_data: &AggregateData,
    file_or_folder: &'a Node,
    heap: &mut BinaryHeap<&'a Node>,
) {
    heap.extend(
        file_or_folder
            .children
            .iter()
            .filter(|c| passes_filters(display_data, c)),
    )
}

fn recursive_rebuilder(allowed_nodes: &HashSet<*const Node>, current: &Node) -> DisplayNode {
    let mut new_children: Vec<DisplayNode> = current
        .children
        .iter()
        .filter(|c| allowed_nodes.contains(&(*c as *const Node)))
        .map(|c| recursive_rebuilder(allowed_nodes, c))
        .collect();
    new_children.sort_by(|lhs, rhs| rhs.cmp(lhs));
    DisplayNode {
        name: current.name.clone(),
        size: current.size,
        children: new_children,
    }
}

// Top-level directories sharing a short name get their parent appended.
fn handle_duplicate_top_level_names(top_level_nodes: Vec<Node>, short_paths: bool) -> Vec<Node> {
    let mut top_level_names: HashSet<String> = HashSet::new();
    let mut dupes: HashSet<String> = HashSet::new();
    for node in &top_level_nodes {
        let name = get_printable_name(&node.name, short_paths);
        if !top_level_names.insert(name.clone()) {
            dupes.insert(name);
        }
    }
    if dupes.is_empty() {
        return top_level_nodes;
    }
    top_level_nodes
        .into_iter()
        .map(|mut n| {
            let name = get_printable_name(&n.name, short_paths);
            if dupes.contains(&name) {
                let parent_name = n
                    .name
                    .parent()
                    .and_then(Path::file_name)
                    .map(|p| p.to_string_lossy().to_string());
                if let Some(p) = parent_name {
                    n.name = PathBuf::from(format!("{name}({p})"));
                }
            }
            n
        })
        .collect()
}
