    let invert_filter_regexs = get_regex_value(options.get_many::<String>("invert_filter"));

    let terminal_width: usize = match options.get_one::<usize>("width") {
        Some(&val) => val,
        None => get_width_of_terminal(),
    };

    let depth = config.get_depth(&options);

    // If depth is set, then we set the default number_of_lines to be max
    // instead of screen height
    let number_of_lines = match config.get_number_of_lines(&options) {
        Some(val) => val,
        None => {
            if depth != usize::MAX {
                usize::MAX
            } else {
                get_height_of_terminal()
            }
        }
    };

    let is_colors = config.get_force_colors(&options)
        || !(init_color(config.get_no_colors(&options)) || get_terminal_size().is_none());

    let ignore_directories = match options.get_many::<PathBuf>("ignore_directory") {
        Some(values) => values.cloned().collect::<Vec<PathBuf>>(),
        None => vec![],
    };

    let ignore_from_file_result = options.get_one::<String>("ignore_all_in_file").map(|path| {
        let ignore_file = path;
        std::fs::read_to_string(ignore_file)
            .unwrap()
            .lines()
            .map(Regex::new)
            .filter_map(Result::ok)
            .collect::<Vec<Regex>>()
    });
    let ignore_from_file = ignore_from_file_result.unwrap_or_default();

    let invert_filter_regexs = invert_filter_regexs
        .into_iter()
        .chain(ignore_from_file)
        .collect::<Vec<Regex>>();

    let by_filecount = options.get_flag("by_filecount");
    let by_filetime = config.get_filetime(&options);
    let limit_filesystem = options.get_flag("limit_filesystem");
    let follow_links = options.get_flag("dereference_links");

    let allowed_filesystems = if limit_filesystem {
        get_filesystem_devices(&target_dirs)
    } else {
        HashSet::new()
    };

    let simplified_dirs = simplify_dir_names(&target_dirs);

    let ignored_full_path: HashSet<PathBuf> = ignore_directories
        .iter()
        .flat_map(|x| simplified_dirs.iter().map(move |d| d.join(x)))
        .collect();
    let ignored_canonical: HashSet<PathBuf> = ignore_directories
        .iter()
        .filter(|x| x.is_absolute())
        .filter_map(|x| std::fs::canonicalize(x).ok())
        .collect();

    let keep_collapsed: HashSet<PathBuf> = match options.get_many::<String>("collapse") {
        Some(collapse) => collapse
            .flat_map(|x| simplified_dirs.iter().map(move |d| d.join(x)))
            .collect(),
        None => HashSet::new(),
    };

    let filter_modified_time = config.get_modified_time_operator(&options);
    let filter_accessed_time = config.get_accessed_time_operator(&options);
    let filter_changed_time = config.get_changed_time_operator(&options);

    let ignore_hidden = config.get_ignore_hidden(&options);
    let output_format = config.get_output_format(&options);
    let min_size = config.get_min_size(&options);
    let only_dir = config.get_only_dir(&options);
    let only_file = config.get_only_file(&options);
    let full_paths = config.get_full_paths(&options);
    let skip_total = config.get_skip_total(&options);
    let output_json = config.get_output_json(&options);
    let print_errors = config.get_print_errors(&options);
    let no_bars = config.get_no_bars(&options);
    let is_reversed = !config.get_reverse(&options);
    let screen_reader = config.get_screen_reader(&options);
    let bars_on_right = config.get_bars_on_right(&options);
    let use_apparent_size = config.get_apparent_size(&options);
    let disable_progress = config.get_disable_progress(&options);

    let mut indicator = PIndicator::build_me();
    if !disable_progress {
        indicator.spawn(output_format.clone());
    }

    let walk_data = WalkData {
        ignore_directories: ignored_full_path,
        ignore_canonical: ignored_canonical,
        filter_regex: &filter_regexs,
        invert_filter_regex: &invert_filter_regexs,
        allowed_filesystems,
        filter_modified_time,
        filter_accessed_time,
        filter_changed_time,
        use_apparent_size,
        by_filecount,
        by_filetime,
        ignore_hidden,
        follow_links,
        progress_data: indicator.data.clone(),
        errors: errors_for_rayon,
    };

    let threads_to_use = config.get_threads(&options);
    let stack_size = config.get_stack_size(&options);

    let pool = init_rayon(&stack_size, &threads_to_use);
    let using_a_filter = !filter_regexs.is_empty() || !invert_filter_regexs.is_empty();

    pool.install(|| {
        let top_level_nodes = walk_it(simplified_dirs, &walk_data);

        // Must have stopped indicator before we print to stderr
        indicator.stop();

        let errors_final = walk_data.errors.lock().unwrap();
        print_any_errors(print_errors, &errors_final);

        let tree = if summarize_file_types {
            get_all_file_types(&top_level_nodes, number_of_lines)
        } else {
            let agg_data = AggregateData {
                min_size,
                only_dir,
                only_file,
                number_of_lines,
                depth,
                using_a_filter,
                short_paths: !full_paths,
            };
            get_biggest(top_level_nodes, agg_data, &keep_collapsed)
        };

        if tree.children.is_empty() && !errors_final.file_not_found.is_empty() {
            std::process::exit(1)
        }

        if output_json {
            let jn = JsonNode { node: &tree, output_format: &output_format, by_filecount };
            let serialized: String = serde_json::to_string(&jn).unwrap();
            println!("{serialized}");
        } else {
            let idd = InitialDisplayData {
                short_paths: !full_paths,
                is_reversed,
                colors_on: is_colors,
                by_filecount,
                by_filetime,
                is_screen_reader: screen_reader,
                output_format,
                bars_on_right,
            };
            draw_it(idd, no_bars, terminal_width, &tree, skip_total);
        }
    });
}

fn init_rayon(stack: &Option<usize>, threads: &Option<usize>) -> rayon::ThreadPool {
    let stack_size = stack.unwrap_or(DEFAULT_STACK_SIZE).max(MIN_STACK_SIZE);
    let mut builder = rayon::ThreadPoolBuilder::new().stack_size(stack_size);
    if let Some(t) = threads {
        builder = builder.num_threads(*t);
    }
    match builder.build() {
        Ok(pool) => pool,
        Err(_) => rayon::ThreadPoolBuilder::new()
            .build()
            .expect("failed to build thread pool"),
    }
}
