/// A POSIX TZ value naming a daylight saving zone without transition rules
/// (for example `EST5EDT` when no zoneinfo file of that name exists) is
/// treated as UTC.
fn normalize_timezone() {
    let tz = match std::env::var("TZ") {
        Ok(tz) => tz,
        Err(_) => return,
    };
    if tz.is_empty() || tz.starts_with(':') || tz.starts_with('/') || tz.contains(',') {
        return;
    }
    if std::path::Path::new("/usr/share/zoneinfo").join(&tz).is_file() {
        return;
